536	function readBody(req) {
537	  return new Promise((resolve, reject) => {
538	    let data = '';
539	    req.on('data', (chunk) => {
540	      data += chunk;
541	      if (data.length > 64_000) req.destroy(new Error('body too large'));
542	    });
543	    req.on('end', () => {
544	      if (!data) return resolve({});
545	      try {
546	        resolve(JSON.parse(data));
547	      } catch {
548	        reject(new Error('invalid JSON body'));
549	      }
550	    });
551	    req.on('error', reject);
552	  });
553	}
