input.command:
node -e "
function fmtDur(ms) {
  if (ms == null || !isFinite(ms) || ms < 0) return '';
  var s = Math.floor(ms / 1000);
  if (s < 60) return s + 's';
  var m = Math.floor(s / 60);
  if (m < 60) return m + 'm ' + (s % 60) + 's';
  var h = Math.floor(m / 60);
  return h + 'h ' + (m % 60) + 'm';
}
function testGuard(bot) {
  if (bot.offline || bot.idleGuard == null) return 'HIDDEN';
  return bot.idleGuard ? 'guard on' : 'guard off (warn)';
}
function testDeath(bot) {
  if (bot.lastDeath && bot.lastDeath.ts) {
    var diedAgo = fmtDur(Date.now() - Date.parse(bot.lastDeath.ts));
    return diedAgo ? '(' + diedAgo + ' ago)' : 'HIDDEN(bad ts math)';
  }
  return 'HIDDEN';
}
console.log('offline bot:', testGuard({offline:true, idleGuard:null}), testDeath({lastDeath:null}));
console.log('online guard on:', testGuard({offline:false, idleGuard:true}));
console.log('online guard off:', testGuard({offline:false, idleGuard:false}));
console.log('null idleGuard (old runner):', testGuard({offline:false, idleGuard:null}));
console.log('death 3m ago:', testDeath({lastDeath:{ts:new Date(Date.now()-3*60000).toISOString()}}));
console.log('death bad ts:', testDeath({lastDeath:{ts:'not-a-date'}}));
"

